/* Master clocks for one access at a 24-bit address. memsel = $420D bit 0. */
static inline int snes_region_speed(uint32_t addr24, int memsel) {
    uint8_t bank = (uint8_t)(addr24 >> 16);
    uint16_t addr = (uint16_t)(addr24 & 0xFFFF);
    if (bank >= 0x40 && bank <= 0x7F) return SNES_CYC_SLOW;
    if (bank >= 0xC0)                 return memsel ? SNES_CYC_FAST : SNES_CYC_SLOW;
    if (addr >= 0x8000) {
        if (bank <= 0x3F)             return SNES_CYC_SLOW;       /* LoROM */
        return memsel ? SNES_CYC_FAST : SNES_CYC_SLOW;            /* WS2 LoROM */
    }
    if (addr < 0x2000)                return SNES_CYC_SLOW;       /* WRAM mirror */
    if (addr < 0x4000)                return SNES_CYC_FAST;       /* PPU/APU/I/O */
    if (addr < 0x4200)                return SNES_CYC_XSLOW;      /* joypad/I/O */
    if (addr < 0x6000)                return SNES_CYC_FAST;       /* $4200-$5FFF */
    return SNES_CYC_SLOW;                                         /* $6000-$7FFF */
}

/* ---------------------------------------------------------------------------
 * SHARED TIMING CONTRACT (STC)
 *
 * The authority above is the datasheet model.  The STC is that authority
 * RESTRICTED to the predicates the v2 emitter actually emits, so the generated
 * tier and the reference interpreter charge the same thing by construction
 * rather than by two matching omissions.  Both consumers read these macros;
 * neither re-derives the rule.
 *
 * DECLARED RESIDUALS (charged by NEITHER tier):
 *   R1  xcross_add for INDIR_Y (7 read opcodes)
 *       opcodes: $11 $31 $51 $71 $B1 $D1 $F1
 *       reason:  runtime DP pointer is not reconstructable from the static operand
 *   R2  block_move per-byte for MVN/MVP
 *       opcodes: $44 $54
 *       reason:  the block constant counts one byte; the transfer loop is uncharged
 *
 * Closing a residual means changing snes_cycles.py and regenerating this
 * header: both consumers then move together, in one commit.
 * --------------------------------------------------------------------------- */

/* The STC's index-page-cross charge for `op`, on a GENUINE cross:
 *   read / RMW abs,X / abs,Y  -> 1     (an indexed read pays for the carry)
 *   indexed store             -> 0     (already folded into the store base)
 *   (dp),Y read               -> 0     (residual R1)
 * This is the ONLY indexed-cross rule either tier may use. */
#define SNES_STC_XCROSS(op) ((int)(SNES_XCROSS_ADD[(op)] & SNES_XCROSS_EMITTED[(op)]))

/* "This indexed access crossed a 256-byte page", spelled exactly as the
 * emitter writes it into generated C (snes_cycles.xcross_predicate_c).  The
 * 16-bit mask on both sides is load-bearing: an indexed access that carries
 * out of the bank must compare equal to itself in both tiers. */
#define SNES_STC_INDEX_CROSS(base, index) ((((uint32_t)(base)) & 0xFF00) != ((((uint32_t)(base)) + ((uint32_t)(index))) & 0xFF00))

/* MVN/MVP charge 7 master-equivalent CPU cycles PER BYTE moved; handle them
 * out of band (the byte count is the A register at execution).  The emitter
 * does NOT emit that per-byte charge (residual R2), so generated block-move
 * execution is not tier-safe and is asserted unreachable at runtime by
 * SNESRECOMP_BLOCK_MOVE_GATE rather than modelled here. */
#define SNES_STC_BLOCK_MOVE_EMITTED 0
#define SNES_OP_IS_BLOCK_MOVE(op) ((op) == 0x44 || (op) == 0x54)

/* Total CPU (bus) cycles for one execution of `op`. Mirrors the Python
 * authority instr_cpu_cycles(); see snes_cycles.py for flag meanings. */
static inline int snes_instr_cpu_cycles(
        uint8_t op, int m, int x, int e,
        int dp_low_nonzero, int index_page_cross,
        int branch_taken, int branch_page_cross) {
    int c = SNES_BASE_CYCLES[op];
    if (m == 0) c += SNES_M_ADD[op];
    if (x == 0) c += SNES_X_ADD[op];
    if (dp_low_nonzero) c += SNES_DP_ADD[op];
    if (index_page_cross) c += SNES_XCROSS_ADD[op];
    switch (SNES_BRANCH_CLASS[op]) {
        case 1: /* conditional */
            if (branch_taken) { c += 1; if (e == 1 && branch_page_cross) c += 1; }
            break;
        case 2: /* BRA: base already counts the take */
            if (e == 1 && branch_page_cross) c += 1;
            break;
        default: break;
    }
    if (e == 0) c += SNES_E_ADD[op];
    return c;
}

